<template>
  <div class="wt-api-manual">
    <header><div><div class="wt-page-kicker">WONDERTRADER / PYTHON API</div><h1>策略 API 手册</h1><p>按当前容器中的 wtpy 源码生成，参数、回调与引擎保持一致。</p></div><router-link to="/backtest" class="wt-manual-back">← 返回在线回测</router-link></header>
    <div class="wt-api-tools"><el-radio-group v-model="type" aria-label="API策略类型"><el-radio-button value="cta">CTA</el-radio-button><el-radio-button value="hft">HFT</el-radio-button><el-radio-button value="sel">SEL</el-radio-button></el-radio-group><el-input v-model="search" clearable placeholder="搜索函数名或说明，例如 enter_long" aria-label="搜索API"/><span>{{filtered.length}} 个接口</span></div>
    <section class="wt-api-primer"><h2>{{primers[type].title}}</h2><p>{{primers[type].description}}</p><div class="wt-api-callbacks"><code v-for="callback in primers[type].callbacks" :key="callback">{{callback}}</code></div><p class="wt-api-boundary">{{primers[type].boundary}}</p><pre>{{primers[type].example}}</pre></section>
    <div class="wt-api-list"><article v-for="entry in filtered" :key="entry.type+entry.name" :id="entry.name"><div class="wt-api-entry-heading"><h3>{{entry.name}}</h3><a :href="'#'+$route.path+'?type='+type+'#'+entry.name" @click.prevent="copyName(entry.name)" title="复制函数名">复制名称</a></div><code class="wt-api-signature">{{entry.signature}}</code><pre>{{entry.description}}</pre><small>源码 {{entry.source}}:{{entry.line}}</small></article><el-empty v-if="!filtered.length" description="没有匹配的接口"/></div>
    <footer>此页面记录当前已安装版本。回测成交依赖数据、费用与成交模型；API 调用成功不代表实盘委托已经成交。</footer>
  </div>
</template>
<script>
import entries from '@/data/wt-api.json'
const primers={
  cta:{title:'CTA：用持仓意图表达交易',description:'策略继承 BaseCtaStrategy，使用 CtaContext。主 K 线驱动 on_calculate；on_tick 接收已订阅合约的行情，on_bar 处理 K 线事件。',callbacks:['on_init(context)','on_tick(context, stdCode, newTick)','on_bar(context, stdCode, period, newBar)','on_calculate(context)'],boundary:'stra_enter_long 是策略层的做多指令，内部处理已有空仓；它不是直接返回交易所订单号的报单接口。stra_set_position 的 qty 是目标净持仓。不要把 enter_long 的 qty 当作目标仓位反复传入。价格条件、成交时点和费用由所选引擎、执行器与成交模型决定。',example:'def on_calculate(self, context):\n    bars = context.stra_get_bars(self.code, "m1", 60, isMain=True)\n    if bars is None:\n        return\n    # 在这里编写信号；示例不自动交易\n    # context.stra_enter_long(self.code, 1, "entry")\n    # context.stra_exit_long(self.code, 1, "exit")'},
  hft:{title:'HFT：跟踪委托、成交和撤单',description:'策略继承 BaseHftStrategy，使用 HftContext。行情回调中生成交易决策，通过 on_entrust、on_order、on_trade 跟踪完整订单生命周期。',callbacks:['on_init(context)','on_tick(context, stdCode, newTick)','on_channel_ready(context)','on_channel_lost(context)','on_entrust(...)','on_order(...)','on_trade(...)'],boundary:'stra_buy / stra_sell 返回本地订单号列表，空列表表示未生成订单；收到成交回报后才能确认成交。stra_cancel 需要本地订单号。市价、FAK、FOK 能否使用仍取决于交易通道与交易所支持。HFT Mocker 需要可用的 Tick 数据，K 线不能替代逐笔撮合数据。',example:'def on_tick(self, context, stdCode, newTick):\n    # 先判断通道、行情、风控与重复订单，再决定委托\n    # local_ids = context.stra_buy(stdCode, price, 1, "entry", 0)\n    pass\n\ndef on_trade(self, context, localid, stdCode, isBuy, qty, price, userTag):\n    # 更新成交与风险状态，不以发送成功代替成交\n    pass'},
  sel:{title:'SEL：按计划调度，设置目标仓位',description:'策略继承 BaseSelStrategy，使用 SelContext。引擎根据注册的日期、时间与周期进行调度，Python 策略实现的回调名称是 on_calculate。',callbacks:['on_init(context)','on_session_begin(context, curTDate)','on_calculate(context)','on_session_end(context, curTDate)'],boundary:'Python BaseSelStrategy 没有供用户实现的 on_schedule 回调；引擎内部调度会转发到 on_calculate。新模板的 schedule 配置决定触发时间。stra_set_position 设置目标仓位，并不是在当前仓位上追加。',example:'def on_calculate(self, context):\n    bars = context.stra_get_bars(self.code, "m1", 60)\n    if bars is None:\n        return\n    # 根据选股/择时结果设置目标仓位\n    # context.stra_set_position(self.code, target_qty, "rebalance")\n    pass'}
}
export default{name:'ApiManual',data(){return{entries,primers,type:['cta','hft','sel'].includes(this.$route.query.type)?this.$route.query.type:'cta',search:''}},computed:{filtered(){const term=this.search.toLowerCase().trim();return this.entries.filter(entry=>entry.type===this.type&&(!term||(entry.name+' '+entry.description).toLowerCase().includes(term)))}},methods:{async copyName(name){try{await navigator.clipboard.writeText(name);this.$message.success('已复制 '+name)}catch{this.$message.info(name)}}}}
</script>
<style scoped>
.wt-api-manual{max-width:1120px;height:100%;overflow:auto;margin:0 auto;padding:32px 38px;color:var(--wt-text)}header{display:flex;justify-content:space-between;gap:20px;align-items:flex-start}.wt-page-kicker{font-size:9px;letter-spacing:1.8px;color:var(--wt-muted)}h1{font-size:25px;font-weight:550;margin:12px 0}header p{font-size:12px;color:var(--wt-muted)}.wt-manual-back{font-size:12px;color:var(--wt-muted);text-decoration:none;white-space:nowrap;margin-top:25px}.wt-api-tools{display:flex;gap:16px;align-items:center;padding:22px 0;border-bottom:1px solid var(--wt-line);position:sticky;top:0;background:var(--wt-surface);z-index:3}.wt-api-tools .el-input{max-width:380px}.wt-api-tools>span{margin-left:auto;white-space:nowrap;font-size:11px;color:var(--wt-muted)}.wt-api-primer{padding:24px 0 28px;border-bottom:1px solid var(--wt-line)}h2{font-size:17px;font-weight:550}p{font-size:12px;line-height:1.9}.wt-api-callbacks{display:flex;gap:6px;flex-wrap:wrap;margin:16px 0}.wt-api-callbacks code{font:10px var(--wt-mono);background:var(--wt-hover);padding:5px 7px;border-radius:4px}.wt-api-boundary{color:var(--wt-muted)}pre{font:12px/1.9 var(--wt-mono);white-space:pre-wrap;overflow-wrap:anywhere}.wt-api-primer pre{background:var(--wt-matte);padding:18px 20px;border:1px solid var(--wt-line);border-radius:8px;color:var(--wt-muted)}article{padding:22px 0;border-bottom:1px solid var(--wt-line);scroll-margin-top:80px}.wt-api-entry-heading{display:flex;align-items:center;justify-content:space-between;gap:10px}h3{font:600 14px var(--wt-mono);margin:0 0 12px}.wt-api-entry-heading a{color:var(--wt-muted);font-size:10px;text-decoration:none}.wt-api-signature{display:block;font:11px/1.8 var(--wt-mono);background:var(--wt-matte);padding:10px 12px;border-radius:6px;overflow-wrap:anywhere}article pre{font-size:12px;font-family:var(--el-font-family)}article small{color:var(--wt-muted);font:10px var(--wt-mono)}footer{font-size:11px;line-height:1.8;color:var(--wt-muted);padding:26px 0}
@media(max-width:900px){.wt-api-manual{padding:20px}.wt-api-tools{flex-wrap:wrap}.wt-api-tools .el-input{max-width:none;flex:1}.wt-api-tools>span{display:none}.wt-manual-back{font-size:10px}}
</style>
